 * 第三方字体继续遵守其原许可证。
 */

@font-face {
    font-family: "LXGW WenKai";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/lxgwwenkai/lxgwwenkai.woff2") format("woff2");
    font-weight: 400;
    font-style: normal;
    font-display: swap;
}

@font-face {
    font-family: "Special Elite";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/special-elite/SpecialElite-Regular.woff2") format("woff2");
    font-weight: 400;
    font-style: normal;
    font-display: swap;
}

:root {
    --sw-navy: #22313e;
    --sw-navy-deep: #1b2833;
    --sw-blue: #7895a6;
    --sw-blue-pale: #a8bfca;
    --sw-cream: #f0dfb9;
    --sw-cream-pale: #f7edd0;
    --sw-brick: #8d3f2c;
    --sw-brick-deep: #6f3024;
    --sw-cocoa: #4d241c;
    --sw-ink: #302a25;
    --sw-muted: #536b78;
    --sw-success: #5f7d68;
    --sw-warning: #a56d37;
    --sw-error: #9c4536;
    --sw-info: #5c7b8d;
    --sw-line: 2px solid var(--sw-cocoa);
    --sw-hairline: 1px solid rgb(77 36 28 / 55%);
    --sw-radius: 3px;
    --sw-shadow: 0 8px 0 rgb(20 30 38 / 24%);
    --sw-font-body: "LXGW WenKai", "Microsoft YaHei UI", "PingFang SC", sans-serif;
    --sw-font-label: "Special Elite", "LXGW WenKai", "Microsoft YaHei UI", sans-serif;
    --avatar-size: 0px;
    --avatar-gap: 0px;
    --avatar-slot: calc(var(--avatar-size) + var(--avatar-gap));
    --sw-asset-wrapper: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/540499a4fadd7cfe328dc3e88d1020ae86ed713b/assets/%E7%B3%96%E7%BA%B8%E6%8B%BC%E8%B4%B4/wrapper-paper.png");
    --sw-asset-topbar: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/540499a4fadd7cfe328dc3e88d1020ae86ed713b/assets/%E7%B3%96%E7%BA%B8%E6%8B%BC%E8%B4%B4/topbar-objects.png");
    --sw-asset-input: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/540499a4fadd7cfe328dc3e88d1020ae86ed713b/assets/%E7%B3%96%E7%BA%B8%E6%8B%BC%E8%B4%B4/input-objects.png");
}

body {
    font-family: var(--sw-font-body);
    color: var(--sw-cream-pale);
    background-color: var(--sw-navy-deep);
}


/* ===== kernel/function-protection.css ===== */
/* Functional guardrails and state fallbacks. No theme geometry belongs here. */

#top-settings-holder .drawer-toggle,
#send_form #options_button,
#send_form #send_but,
#send_form #mes_stop,
#send_form .fa-wand-magic,
#send_form .fa-wand-magic-sparkles {
    min-inline-size: 2.25rem;
    min-block-size: 2.25rem;
}

#top-settings-holder .drawer-icon:focus-visible,
#send_form .interactable:focus-visible,
#send_form .mes_stop:focus-visible,
#chat .mes_button:focus-visible,
.popup button:focus-visible,
.menu_button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
    outline: 2px solid var(--sw-cream);
    outline-offset: 2px;
}

#chat .mes_text,
#chat .mes_reasoning {
    overflow-wrap: anywhere;
}

#chat .mes_text pre,
#chat .mes_text table {
    max-inline-size: 100%;
    overflow: auto;
}

#chat .mes_media_wrapper img,
#chat .mes_text img,
#chat .mes_file_wrapper {
    max-inline-size: 100%;
}

#top-settings-holder .drawer-icon,
#send_form #options_button,
#send_form #send_but,
#send_form #mes_stop,
#send_form .fa-wand-magic,
#send_form .fa-wand-magic-sparkles {
    background-repeat: no-repeat;
    pointer-events: auto;
}


/* ===== chat-layout.css ===== */
/* W01: dispatch-wrapper chat shell. Structure and topology gates are confirmed. */

#bg1,
#bg_custom {
    background-color: var(--sw-navy-deep);
    background-image:
        linear-gradient(rgb(27 40 51 / 76%), rgb(27 40 51 / 76%)),
        var(--sw-asset-wrapper);
    background-size: auto, min(76rem, 100vw) auto;
    background-position: center;
}

#chat {
    gap: clamp(1.15rem, 2.6vw, 2rem);
    padding: clamp(1rem, 2.6vw, 2rem);
    background-color: var(--sw-navy);
    background-image:
        linear-gradient(rgb(34 49 62 / 86%), rgb(34 49 62 / 86%)),
        var(--sw-asset-wrapper);
    background-size: auto, min(64rem, 125vw) auto;
    background-position: center top;
    text-shadow: none;
    scrollbar-color: var(--sw-brick) var(--sw-navy-deep);
}

#chat::before {
    content: "SWEET DISPATCH  •  糖纸拼贴  •  LONG FORM";
    display: block;
    align-self: center;
    inline-size: min(88%, 54rem);
    padding: 0.78em 1.2em 0.66em;
    color: var(--sw-cream-pale);
    background-color: var(--sw-brick);
    background-image:
        linear-gradient(90deg, var(--sw-brick) 0 16%, var(--sw-cocoa) 16% 18%, var(--sw-brick) 18% 82%, var(--sw-cocoa) 82% 84%, var(--sw-brick) 84%),
        var(--sw-asset-wrapper);
    background-blend-mode: multiply;
    border-block: 0.34rem double var(--sw-cream);
    outline: 1px solid var(--sw-cocoa);
    font-family: var(--sw-font-label);
    font-size: clamp(0.82rem, 1.8vw, 1.08rem);
    letter-spacing: 0.14em;
    text-align: center;
    box-shadow: 0.5rem 0.5rem 0 rgb(27 40 51 / 72%);
}

#chat .mes {
    flex-direction: column;
    align-items: stretch;
    align-self: flex-start;
    inline-size: 100%;
    max-inline-size: min(84%, 66rem);
    margin: 0;
    padding: 0;
    color: var(--sw-ink);
    background: transparent;
    border: 0;
    border-radius: 0;
    box-shadow: none;
}

#chat .mes[is_user="true"] {
    align-self: flex-end;
    max-inline-size: min(52%, 42rem);
    color: var(--sw-cream-pale);
}

#chat .mes[is_user="false"][is_system="false"]:nth-of-type(4n + 3) {
    align-self: flex-end;
    max-inline-size: min(88%, 68rem);
}

#chat .mes[is_system="true"] {
    align-self: center;
    max-inline-size: min(74%, 54rem);
    color: var(--sw-cream-pale);
}

#chat .mes.smallSysMes {
    padding: 0 !important;
}

#chat .mes .mesAvatarWrapper {
    display: flex;
    flex: 0 0 auto;
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.35em;
    inline-size: fit-content;
    min-block-size: 0;
    margin: 0 0 0.4em 0.6rem;
    padding: 0.22em 0.72em;
    color: var(--sw-cream-pale);
    background: var(--sw-navy-deep);
    border-inline-start: 0.38rem solid var(--sw-blue);
    border-block-end: 1px dashed var(--sw-cream);
    font-family: var(--sw-font-label);
}

#chat .mes[is_user="true"] .mesAvatarWrapper {
    align-self: flex-end;
    margin-inline: 0 0.6rem;
    background: var(--sw-cocoa);
    border-inline-start-color: var(--sw-cream);
}

#chat .mes .mesAvatarWrapper .avatar {
    display: none !important;
}

#chat .mes .mes_timer,
#chat .mes .mesIDDisplay,
#chat .mes .tokenCounterDisplay {
    padding: 0;
    color: inherit;
    background: transparent;
    border: 0;
    opacity: 0.78;
    font-size: 0.72em;
    font-weight: 400;
    text-shadow: none;
}

#chat .mes_block {
    flex: 1 1 auto;
    min-inline-size: 0;
    inline-size: 100%;
    padding: clamp(0.95rem, 2.3vw, 1.65rem) clamp(1.15rem, 3.5vw, 3rem) clamp(1.15rem, 2.8vw, 2rem);
    color: var(--sw-ink);
    background-color: var(--sw-cream);
    background-image:
        linear-gradient(90deg, var(--sw-blue) 0 0.72rem, transparent 0.72rem calc(100% - 0.48rem), var(--sw-brick) calc(100% - 0.48rem)),
        linear-gradient(rgb(240 223 185 / 91%), rgb(240 223 185 / 91%)),
        var(--sw-asset-wrapper);
    background-size: auto, auto, 48rem auto;
    background-position: center;
    border: 0.14rem solid var(--sw-cocoa);
    border-block: 0.48rem double var(--sw-brick);
    border-radius: 0;
    box-shadow: 0.62rem 0.62rem 0 var(--sw-navy-deep), 0.82rem 0.82rem 0 rgb(120 149 166 / 46%);
    text-shadow: none;
}

#chat .mes[is_user="false"][is_system="false"]:nth-of-type(4n + 3) .mes_block {
    background-image:
        linear-gradient(90deg, var(--sw-brick) 0 0.52rem, transparent 0.52rem calc(100% - 0.72rem), var(--sw-blue) calc(100% - 0.72rem)),
        linear-gradient(rgb(247 237 208 / 92%), rgb(247 237 208 / 92%)),
        var(--sw-asset-wrapper);
    border-block-color: var(--sw-blue);
    box-shadow: -0.62rem 0.62rem 0 var(--sw-navy-deep), -0.82rem 0.82rem 0 rgb(141 63 44 / 46%);
}

#chat .mes[is_user="true"] .mes_block {
    padding: 0.85rem clamp(1rem, 2.4vw, 1.65rem) 1rem;
    color: var(--sw-cream-pale);
    background-color: var(--sw-brick);
    background-image:
        linear-gradient(90deg, transparent 0 0.58rem, rgb(240 223 185 / 16%) 0.58rem 0.72rem, transparent 0.72rem),
        linear-gradient(rgb(141 63 44 / 92%), rgb(141 63 44 / 92%)),
        var(--sw-asset-wrapper);
    background-position: center;
    border: 0.14rem solid var(--sw-cream);
    border-block: 0.34rem double var(--sw-cream);
    outline: 1px solid var(--sw-cocoa);
    box-shadow: 0.48rem 0.48rem 0 var(--sw-cocoa);
}

#chat .mes[is_system="true"] .mes_block {
    color: var(--sw-cream-pale);
    background: var(--sw-muted);
    border: 1px dashed var(--sw-cream);
    box-shadow: 0.42rem 0.42rem 0 var(--sw-navy-deep);
}

#chat .mes_block::before {
    content: "STORY PACK  /  CHARACTER DISPATCH";
    display: block;
    margin: -0.25em 0 0.72em;
    padding-block: 0.22em;
    color: var(--sw-brick-deep);
    border-block: 1px dashed currentColor;
    font-family: var(--sw-font-label);
    font-size: 0.78em;
    letter-spacing: 0.12em;
    text-align: center;
}

#chat .mes[is_user="true"] .mes_block::before {
    content: "ORDER NOTE  /  USER";
    color: var(--sw-cream-pale);
}

#chat .mes[is_system="true"] .mes_block::before {
    content: "SERVICE NOTICE";
    color: inherit;
}

#chat .mes.selected .mes_block {
    outline: 3px solid var(--sw-warning);
    outline-offset: 3px;
}

#chat .mes_block .ch_name {
    min-block-size: 0;
    margin: 0 0 0.72em;
    padding: 0.38em 0.62em;
    color: var(--sw-cream-pale);
    background: var(--sw-navy-deep);
    border-inline-start: 0.46rem solid var(--sw-brick);
    font-family: var(--sw-font-label);
    letter-spacing: 0.045em;
}

#chat .mes[is_user="true"] .mes_block .ch_name {
    color: var(--sw-cocoa);
    background: var(--sw-cream);
    border-inline-start-color: var(--sw-blue);
}

#chat .mes_block .name_text {
    font-size: 1.04em;
    font-weight: 400;
    text-transform: uppercase;
}

#chat .mes_block .timestamp {
    color: inherit;
    opacity: 0.72;
    font-size: 0.76em;
}

#chat .mes_buttons,
#chat .extraMesButtons {
    color: inherit;
    overflow-x: auto;
}

#chat .mes_button,
#chat .extraMesButtons > div {
    color: inherit;
    filter: none;
    opacity: 0.56;
    text-shadow: none;
}

#chat .mes_button:hover,
#chat .mes_button:focus-visible,
#chat .extraMesButtons > div:hover,
#chat .extraMesButtons > div:focus-visible {
    opacity: 1;
}

#chat .swipe_left,
#chat .swipe_right,
#chat .swipes-counter {
    color: currentColor;
    filter: none;
    text-shadow: none;
}

#chat .mes_reasoning_details {
    margin: 0.55em 0 0.9em;
    padding: 0.72em 0.9em;
    color: var(--sw-ink);
    background: var(--sw-blue-pale);
    border: 1px dashed var(--sw-cocoa);
    box-shadow: none;
    text-shadow: none;
}

#chat .mes_reasoning_details[data-state="thinking"] {
    color: var(--sw-cream-pale);
    background: var(--sw-muted);
    border-color: var(--sw-cream);
}


/* ===== full-text.css ===== */
/* T02: editorial long-RP typography. No parent geometry compensation here. */

#chat .mes_text {
    inline-size: 100%;
    max-inline-size: 68ch;
    margin-inline: auto;
    padding: 0.18em 0 0.3em;
    color: inherit;
    font-family: var(--sw-font-body);
    font-size: 1em;
    font-weight: 400;
    line-height: 1.72;
    text-align: start;
    text-shadow: none;
}

#chat .mes[is_user="true"] .mes_text {
    max-inline-size: 58ch;
    line-height: 1.58;
}

#chat .mes_text p {
    margin-block: 0 0.82em;
}

#chat .mes_text p:last-child {
    margin-block-end: 0;
}

#chat .mes_text h1,
#chat .mes_text h2,
#chat .mes_text h3,
#chat .mes_text h4 {
    margin: 1.08em 0 0.55em;
    color: var(--sw-brick-deep);
    font-family: var(--sw-font-label);
    font-weight: 400;
    line-height: 1.25;
    letter-spacing: 0.045em;
}

#chat .mes[is_user="true"] .mes_text h1,
#chat .mes[is_user="true"] .mes_text h2,
#chat .mes[is_user="true"] .mes_text h3,
#chat .mes[is_user="true"] .mes_text h4 {
    color: var(--sw-cream);
}

#chat .mes_text blockquote {
    margin: 1em 0;
    padding: 0.65em 1em;
    color: var(--sw-cocoa);
    background: rgb(168 191 202 / 34%);
    border: 0;
    border-inline-start: 0.45em solid var(--sw-brick);
}

#chat .mes[is_user="true"] .mes_text blockquote {
    color: var(--sw-cream-pale);
    background: rgb(77 36 28 / 28%);
    border-inline-start-color: var(--sw-blue-pale);
}

#chat .mes_text strong {
    color: var(--sw-brick-deep);
    font-weight: 400;
    text-decoration: underline;
    text-decoration-thickness: 0.12em;
    text-underline-offset: 0.16em;
}

#chat .mes[is_user="true"] .mes_text strong {
    color: var(--sw-cream);
}

#chat .mes_text em {
    color: var(--sw-muted);
}

#chat .mes_text a {
    color: var(--sw-brick-deep);
    text-decoration-style: dotted;
    text-underline-offset: 0.18em;
}

#chat .mes[is_user="true"] .mes_text a {
    color: var(--sw-blue-pale);
}

#chat .mes_text code,
#chat .mes_text pre {
    color: var(--sw-cream-pale);
    background: var(--sw-navy-deep);
    border-color: var(--sw-blue);
    border-radius: var(--sw-radius);
    font-family: var(--sw-font-label);
    text-shadow: none;
}

#chat .mes_text pre {
    padding: 0.9em 1em;
}

#chat .mes_text table {
    border-collapse: collapse;
    color: var(--sw-ink);
    background: rgb(247 237 208 / 88%);
}

#chat .mes_text th,
#chat .mes_text td {
    padding: 0.45em 0.65em;
    border: var(--sw-hairline);
}

#chat .mes_text th {
    color: var(--sw-cream-pale);
    background: var(--sw-brick);
    font-family: var(--sw-font-label);
    font-weight: 400;
}

#chat .mes_text hr {
    block-size: 0.38em;
    margin-block: 1.4em;
    border: 0;
    border-block: 1px dashed currentColor;
    opacity: 0.68;
}

#chat .mes_text details {
    margin-block: 0.75em;
    padding: 0.6em 0.75em;
    border: 1px dashed currentColor;
}


/* ===== windows/top-bar.css ===== */
/* W02: nine unframed packaging objects. Drawer parent geometry is untouched. */

#top-bar {
    background-color: var(--sw-navy-deep);
    background-image:
        linear-gradient(90deg, rgb(141 63 44 / 20%), transparent 24% 76%, rgb(120 149 166 / 20%)),
        linear-gradient(rgb(27 40 51 / 76%), rgb(27 40 51 / 76%)),
        var(--sw-asset-wrapper);
    background-size: auto, auto, 40rem auto;
    border-block: 0.3rem double var(--sw-cream);
    border-block-end-color: var(--sw-brick);
    box-shadow: 0 4px 0 var(--sw-blue), 0 6px 0 var(--sw-cocoa);
    backdrop-filter: none;
}

#top-settings-holder .drawer-toggle {
    background: transparent;
    border: 0;
    box-shadow: none;
}

#top-settings-holder .drawer-icon {
    color: rgb(240 223 185 / 42%);
    background-color: transparent;
    background-image: var(--sw-asset-topbar);
    background-size: 270% 270%;
    background-origin: content-box;
    background-clip: content-box;
    border: 0;
    border-radius: 0;
    filter: saturate(1.02) contrast(1.04);
    opacity: 1;
    text-shadow: none;
    transition: filter 150ms ease, opacity 150ms ease, transform 150ms ease;
}

#top-settings-holder .drawer-icon:hover,
#top-settings-holder .drawer-icon:focus-visible,
#top-settings-holder .drawer-icon.openIcon {
    filter: saturate(1.18) brightness(1.12) contrast(1.04);
    opacity: 1;
    transform: translateY(-0.08em) scale(1.06);
}

#ai-config-button .drawer-icon { background-position: 0% 0%; }
#sys-settings-button .drawer-icon { background-position: 50% 0%; }
#advanced-formatting-button .drawer-icon { background-position: 100% 0%; }
#WI-SP-button .drawer-icon { background-position: 0% 50%; }
#user-settings-button .drawer-icon { background-position: 50% 50%; }
#backgrounds-button .drawer-icon { background-position: 100% 50%; }
#extensions-settings-button .drawer-icon { background-position: 0% 100%; }
#persona-management-button .drawer-icon { background-position: 50% 100%; }
#rightNavHolder .drawer-icon { background-position: 100% 100%; }


/* ===== windows/input.css ===== */
/* W03: navy dispatch counter with a cream writing slip. */

#send_form {
    color: var(--sw-cream-pale);
    background-color: var(--sw-navy-deep);
    background-image:
        linear-gradient(90deg, rgb(141 63 44 / 26%), transparent 22% 78%, rgb(120 149 166 / 24%)),
        linear-gradient(rgb(27 40 51 / 82%), rgb(27 40 51 / 82%)),
        var(--sw-asset-wrapper);
    background-size: auto, auto, 48rem auto;
    border: 1px solid var(--sw-cocoa);
    border-block-start: 0.42rem double var(--sw-cream);
    border-radius: 0;
    box-shadow: 0 -4px 0 var(--sw-brick), 0 -7px 0 var(--sw-blue);
    backdrop-filter: none;
}

#send_form #nonQRFormItems {
    align-items: stretch;
    column-gap: 0.28em;
}

#send_textarea {
    margin-block: 0.18em;
    padding-inline: 0.85em;
    color: var(--sw-ink);
    background: var(--sw-cream);
    border: 1px dashed var(--sw-cocoa);
    font-family: var(--sw-font-body);
    font-size: 1em;
    text-shadow: none;
    caret-color: var(--sw-brick);
}

#send_textarea::placeholder {
    color: var(--sw-muted);
    opacity: 0.82;
}

#send_form:has(#send_textarea:focus-visible) {
    border-color: var(--sw-brick);
    outline: 2px solid var(--sw-cream);
    outline-offset: 2px;
}

#send_form #options_button,
#send_form #send_but,
#send_form #mes_stop,
#send_form .fa-wand-magic,
#send_form .fa-wand-magic-sparkles {
    color: rgb(240 223 185 / 44%);
    background-color: transparent;
    background-image: var(--sw-asset-input);
    background-size: 190% 190%;
    background-origin: content-box;
    background-clip: content-box;
    border: 0;
    filter: none;
    opacity: 1;
    text-shadow: none;
    transition: filter 150ms ease, opacity 150ms ease, transform 150ms ease;
}

#send_form #options_button { background-position: 0% 0%; }
#send_form .fa-wand-magic,
#send_form .fa-wand-magic-sparkles { background-position: 100% 0%; }
#send_form #send_but { background-position: 0% 100%; }
#send_form #mes_stop { background-position: 100% 100%; }

#send_form #options_button:hover,
#send_form #send_but:hover,
#send_form #mes_stop:hover,
#send_form .fa-wand-magic:hover,
#send_form .fa-wand-magic-sparkles:hover,
#send_form #options_button:focus-visible,
#send_form #send_but:focus-visible,
#send_form #mes_stop:focus-visible {
    filter: brightness(1.14) saturate(1.14);
    opacity: 1;
    transform: scale(1.06);
}

#form_sheld.script_success #send_textarea { --progSuccessColor: var(--sw-success); }
#form_sheld.script_error #send_textarea { --progErrorColor: var(--sw-error); }
#form_sheld.script_aborted #send_textarea { --progAbortedColor: var(--sw-warning); }


/* ===== windows/text-generation.css ===== */
/* W04: text-completion parameters. */

#left-nav-panel,
#textgenerationwebui_api-settings {
    color: var(--sw-ink);
    background-color: var(--sw-cream-pale);
