/* ===== windows/mobile.css ===== */
/* W14: independent 360/390/430px single-column mother layout. */

@media (max-width: 700px) {
    #chat {
        gap: 1rem;
        padding: 0.62rem;
        background-size: auto, 44rem auto;
    }

    #chat::before {
        inline-size: 100%;
        padding-inline: 0.65em;
        letter-spacing: 0.075em;
        box-shadow: 0.28rem 0.28rem 0 var(--sw-navy-deep);
    }

    #chat .mes,
    #chat .mes[is_user="true"],
    #chat .mes[is_user="false"][is_system="false"]:nth-of-type(4n + 3),
    #chat .mes[is_system="true"] {
        align-self: stretch;
        inline-size: 100%;
        max-inline-size: 100%;
        margin-inline: 0;
        padding: 0;
    }

    #chat .mes .mesAvatarWrapper,
    #chat .mes[is_user="true"] .mesAvatarWrapper {
        margin-inline: 0.35rem;
    }

    #chat .mes_block,
    #chat .mes[is_user="true"] .mes_block {
        padding: 0.78rem 1rem 0.95rem;
        background-size: auto, auto, 38rem auto;
        border-block-width: 0.3rem;
        box-shadow: 0.3rem 0.3rem 0 var(--sw-navy-deep);
    }

    #chat .mes[is_user="false"][is_system="false"]:nth-of-type(4n + 3) .mes_block {
        box-shadow: -0.3rem 0.3rem 0 var(--sw-navy-deep);
    }

    #chat .mes_block::before {
        letter-spacing: 0.07em;
    }

    #chat .mes_block .ch_name {
        flex-wrap: wrap;
        row-gap: 0.3em;
    }

    #chat .mes_text,
    #chat .mes[is_user="true"] .mes_text {
        max-inline-size: 100%;
        line-height: 1.66;
    }

    #chat .mes_buttons,
    #chat .extraMesButtons {
        max-inline-size: 100%;
        overflow-x: auto;
    }

    #send_form {
        border-inline-width: 1px;
        box-shadow: 0 -3px 0 var(--sw-brick), 0 -5px 0 var(--sw-blue);
    }

    #send_form #nonQRFormItems,
    #send_form #leftSendForm,
    #send_form #rightSendForm {
        flex-wrap: nowrap;
    }

    #send_form #leftSendForm,
    #send_form #rightSendForm {
        inline-size: auto;
        min-inline-size: 2.25rem;
    }

    #left-nav-panel,
    #rm_api_block,
    #AdvancedFormatting,
    #WorldInfo,
    #user-settings-block,
    #Backgrounds,
    #rm_extensions_block,
    #PersonaManagement,
    #right-nav-panel {
        box-shadow: inset 0 0.32rem 0 var(--sw-brick);
        background-size: auto, 38rem auto;
    }

    .popup,
    .popup-content {
        max-inline-size: calc(100dvw - 1rem);
        max-block-size: calc(100dvh - 1rem);
        overflow: auto;
    }
}


